CREATE PROCEDURE TEST.DYNAMIC_RESOLUTION
(
    IN P_MODE CHAR(1),
    IN P_TABLE VARCHAR(128),
    IN P_ID BIGINT,
    IN P_PROC VARCHAR(128),
    OUT P_COUNT INTEGER
)
LANGUAGE SQL
BEGIN
    DECLARE V_SQL VARCHAR(4000);

    IF P_MODE = 'A' THEN
        SET V_SQL = 'UPDATE CLAIM_A SET STATUS = ''DONE'' WHERE ID = ' || P_ID;
    ELSE
        SET V_SQL = 'UPDATE CLAIM_B SET STATUS = ''DONE'' WHERE ID = ' || P_ID;
    END IF;
    EXECUTE IMMEDIATE V_SQL;

    SET V_SQL = 'DELETE FROM ' || P_TABLE || ' WHERE ID = ' || P_ID;
    EXECUTE IMMEDIATE V_SQL;

    SET V_SQL = 'CALL CLAIMS.' || P_PROC || '(?)';
    EXECUTE IMMEDIATE V_SQL;

    EXECUTE IMMEDIATE 'CALL CLAIMS.STATIC_NOTIFY(?)';

    PREPARE S1 FROM 'SELECT COUNT(*) FROM CLAIM';
    EXECUTE S1 INTO P_COUNT;

    PREPARE S2 FROM 'UPDATE CLAIM SET STATUS = ? WHERE ID = ?';
    EXECUTE S2 USING 'DONE', P_ID;
END;
